param([int]$TimeoutSeconds=30)
$ErrorActionPreference='Stop'
$EngineRoot=Split-Path -Parent $MyInvocation.MyCommand.Path
$Root=Split-Path -Parent $EngineRoot
$DatabaseFile=Join-Path $Root 'Database\items.json'
$ReportFile=Join-Path $Root 'Database\Description-Repair-Report.txt'
$LogDirectory=Join-Path $Root 'Logs'
New-Item -ItemType Directory -Path $LogDirectory -Force|Out-Null
try{Start-Transcript -Path (Join-Path $LogDirectory ('Description-Repair-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.log')) -Force|Out-Null}catch{}
function Clean([string]$s){if(-not $s){return ''};$s=[regex]::Replace($s,'(?is)<(script|style|noscript)\b[^>]*>.*?</\1>',' ');$s=[regex]::Replace($s,'<[^>]+>',' ');$s=[Net.WebUtility]::HtmlDecode($s);return ([regex]::Replace($s,'\s+',' ')).Trim()}
function ExtractDescription([string]$html,[string]$name){$list=New-Object Collections.Generic.List[string];foreach($p in @('(?is)<meta[^>]+name=["'']description["''][^>]+content=["'']([^"'']+)["'']','(?is)<meta[^>]+content=["'']([^"'']+)["''][^>]+name=["'']description["'']','(?is)<meta[^>]+property=["'']og:description["''][^>]+content=["'']([^"'']+)["'']','(?is)<meta[^>]+content=["'']([^"'']+)["''][^>]+property=["'']og:description["'']','(?is)"description"\s*:\s*"((?:\\.|[^"\\])*)"')){foreach($m in [regex]::Matches($html,$p)){$v=$m.Groups[1].Value;try{if($p -match '"description"'){$v=('"'+$v+'"')|ConvertFrom-Json}}catch{};$c=Clean $v;if($c){$list.Add($c)}}};return [string]($list|Where-Object{$_.Length-ge 12-and$_.Length-le 700-and$_-notmatch '^Paldeck|^Find information|^Explore Palworld|^Palworld database'}|Sort-Object Length|Select-Object -First 1)}
if(-not(Test-Path $DatabaseFile)){Write-Host 'Database missing.' -ForegroundColor Red;exit 1}
$db=[IO.File]::ReadAllText($DatabaseFile)|ConvertFrom-Json;$records=@($db.records);$updated=0;$failed=New-Object Collections.Generic.List[string];$i=0
foreach($r in $records){$i++;if($r.description-and$r.description-notmatch '^No description is available'){continue};if(-not$r.page){$failed.Add("$($r.name) [$($r.id)] no page");continue};try{$resp=Invoke-WebRequest -UseBasicParsing -Uri ([string]$r.page) -TimeoutSec $TimeoutSeconds -Headers @{'User-Agent'='Mozilla/5.0 Aegis-Palworld-Suite';'Accept-Language'='en-US,en;q=0.9'};$d=ExtractDescription ([string]$resp.Content) ([string]$r.name);if($d){$r.description=$d;$updated++}else{$failed.Add("$($r.name) [$($r.id)]")}}catch{$failed.Add("$($r.name) [$($r.id)] $($_.Exception.Message)")};if(($i%25)-eq0){Write-Host "Processed $i/$($records.Count) | Added $updated | Unresolved $($failed.Count)" -ForegroundColor DarkGray}}
$db.records=$records;$db.count=$records.Count;[IO.File]::WriteAllText($DatabaseFile,($db|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $Root 'Database\data.js'),'window.PALWORLD_DATA='+($db|ConvertTo-Json -Depth 10 -Compress)+';',[Text.UTF8Encoding]::new($false));$report=@('Aegis Description Repair','========================','Date: '+(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),'Descriptions added: '+$updated,'Unresolved: '+$failed.Count,'')+@($failed);[IO.File]::WriteAllLines($ReportFile,$report,[Text.UTF8Encoding]::new($false));Write-Host "Descriptions added: $updated" -ForegroundColor Green;Write-Host "Unresolved: $($failed.Count)" -ForegroundColor Yellow;try{Stop-Transcript|Out-Null}catch{}
